        }


        .side-nav {
            width: 45px;
            background: rgba(0, 0, 0, 0.4);
            display: flex;
            flex-direction: column;
            border-right: 1px solid var(--border-pink);
            flex-shrink: 0;
        }

        .nav-btn {
            height: 50px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            color: var(--text-dim);
            transition: var(--trans);
