        .mod-title {
            font-family: 'Orbitron', sans-serif;
            font-size: 0.65rem;
            color: var(--neon-purple);
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            gap: 6px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }


        .header-info { display: flex; flex-direction: column; gap: 2px; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px solid rgba(255,255,255,0.05); }
