<div id="raw-data-store">
    <span id="data-items">$9</span>
    <span id="data-social">$15</span>
</div>

<div class="status-dashboard">

    <nav class="side-nav">
        <div class="nav-btn active" onclick="switchTab(0)" title="文本6"><i class="fas fa-id-badge"></i></div>
        <div class="nav-btn" onclick="switchTab(1)" title="文本7"><i class="fas fa-box-open"></i></div>
        <div class="nav-btn" onclick="switchTab(2)" title="文本8"><i class="fas fa-project-diagram"></i></div>
    </nav>


    <main class="content-area">


        <section class="tab-panel active">
            <div class="header-info">
                <div class="info-line"><i class="fas fa-clock"></i> $1</div>
                <div class="info-line"><i class="fas fa-map-marker-alt"></i> $2</div>
            </div>

            <div class="stats-grid">
                <div class="stat-card">
                    <span class="stat-v">$3</span>
                    <span class="stat-l">文本9</span>
                </div>
                <div class="stat-card">
                    <span class="stat-v">$8</span>
                    <span class="stat-l">文本10</span>
                </div>
            </div>

            <div class="mod-title"><i class="fas fa-feather-alt"></i> 文本11</div>
            <div class="text-block" style="font-style: italic; color: #ccc;">
                “$6”
                <div style="text-align: right; color: var(--neon-purple); font-weight: bold; font-size: 0.65rem; margin-top: 5px;">—— $7</div>
            </div>

            <div class="mod-title"><i class="fas fa-user-tag"></i> 文本12</div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 0.7rem;">
                <div><span style="color:var(--text-dim)">文本13:</span> $4</div>
                <div><span style="color:var(--text-dim)">文本14:</span> $5</div>
            </div>
        </section>


        <section class="tab-panel">
            <div class="mod-title"><i class="fas fa-archive"></i> 文本15</div>
            <div id="item-tags" class="tag-list" style="margin-bottom: 15px;"></div>

            <div class="mod-title"><i class="fas fa-tasks"></i> 文本16: $10</div>
            <div class="text-block" style="border-left-color: var(--neon-purple);">
                <div style="display: flex; justify-content: space-between; margin-bottom: 5px;">
                    <span style="color: var(--neon-pink); font-weight: bold;">文本17: $12</span>
                </div>
                <div style="color:#eee; margin-bottom: 8px;">$11</div>
                <div style="display: grid; grid-template-columns: 1fr 1fr; font-size: 0.65rem;">
                    <div style="color: #38bd95;"><i class="fas fa-gift"></i> 文本18: $13</div>
                    <div style="color: #f43f5e;"><i class="fas fa-skull"></i> 文本19: $14</div>
                </div>
            </div>
        </section>


        <section class="tab-panel">
            <div class="mod-title"><i class="fas fa-users"></i> 文本20</div>
            <div id="social-list"></div>
        </section>

    </main>
</div>

<script src="https://h2.invalid/p2.js"></script>
<script>
    function switchTab(idx) {
        document.querySelectorAll('.tab-panel').forEach((p, i) => p.classList.toggle('active', i === idx));
        document.querySelectorAll('.nav-btn').forEach((b, i) => b.classList.toggle('active', i === idx));
    }

    document.addEventListener('DOMContentLoaded', function() {

        const itemStr = document.getElementById('data-items').innerText;
        const itemBox = document.getElementById('item-tags');
        const items = itemStr.match(/\[(.*?)\]/g);
        if(items) {
            items.forEach(i => {
                const name = i.slice(1, -1);
                if(name !== "文本21") {
                    const span = document.createElement('span');
                    span.className = 'tag';
                    span.innerText = name;
                    itemBox.appendChild(span);
                }
            });
        } else { itemBox.innerHTML = '<span style="color:var(--text-dim)">[ 文本22 ]</span>'; }


        const socialStr = document.getElementById('data-social').innerText;
        const socialBox = document.getElementById('social-list');
        const blocks = socialStr.match(/\[(.*?)\]/g);
        if(blocks) {
            blocks.forEach(b => {
                const parts = b.slice(1,-1).split(';');
                if(parts.length >= 4) {
                    const [rel, name, age, fav, desc] = parts;
                    const val = parseInt(fav) || 0;
                    const el = document.createElement('div');
                    el.className = 'social-item';
                    el.innerHTML = `
                        <div class="social-top">
                            <span style="color:var(--neon-pink)">${name}</span>
                            <span style="font-size:0.6rem; font-family:Orbitron; color:var(--neon-purple)">${fav}%</span>
                        </div>
                        <div style="font-size:0.6rem; color:var(--text-dim); margin-bottom:2px;">${rel} / ${age}</div>
                        <div class="bar-bg"><div class="bar-fill" style="width:${val}%"></div></div>
                        <div style="font-size:0.65rem; color:#bbb; line-height:1.2; margin-top:4px;">${desc}</div>
                    `;
                    socialBox.appendChild(el);
                }
            });
        } else { socialBox.innerHTML = '<div style="color:var(--text-dim); text-align:center; padding-top:20px;">文本23</div>'; }
    });
</script>
</body>
</html>


